using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

// Configure the AI client with tool support
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Initialize the research tools
var researchNotes = new ResearchNotes();
var webSearch = new WebSearchTool();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(webSearch.Search),
        AIFunctionFactory.Create(researchNotes.AddNote),
        AIFunctionFactory.Create(researchNotes.GetNotes),
    ]
};

// Get topic from user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the research agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings using the note-taking tool
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary

        Always search at least 2-3 different angles of the topic, take notes on important findings,
        then produce a final summary with your notes as reference.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await client.GetChatResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchNotes.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

// --- Tool Implementations ---

/// <summary>Simulates web search returning results for a query.</summary>
public class WebSearchTool
{
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> Search([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching web: \"{query}\"]");

        // Use a public search API (DuckDuckGo Instant Answer API)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _http.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrEmpty(abstractText))
                results.Add($"Summary: {abstractText}");

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add(text.GetString() ?? "");
                }
            }

            if (results.Count == 0)
                results.Add($"Search results for '{query}': No detailed results available. The topic may require more specific queries.");

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Note-taking tool for the research agent to record findings.</summary>
public class ResearchNotes
{
    private readonly List<string> _notes = [];

    [Description("Add a research note to remember a key finding. Use this to record important information discovered during research.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return "Research notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];
}

