                     if (item.TryGetProperty("Text", out var text))
                         results.Add(text.GetString() ?? "");
                 }
             }

             if (results.Count == 0)
                 results.Add($"Search results for '{query}': No detailed results available. The topic may require more specific queries.");

             return string.Join("\n\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}. Try a different query.";
         }
     }
 }

 /// <summary>Note-taking tool for the research agent to record findings.</summary>
 public class ResearchNotes
 {
     private readonly List<string> _notes = [];

     [Description("Add a research note to remember a key finding. Use this to record important information discovered during research.")]
     public string AddNote([Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  [Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]");
         return $"Note saved successfully. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all research notes collected so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes have been taken yet.";

         return "Research notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
     }

     public List<string> GetAllNotes() => [.. _notes];
 }
